WITH payload AS (SELECT '{{$json.payload_sql}}'::jsonb AS body), upsert_job AS (
INSERT INTO content_jobs (external_job_ref, project_name, brief_text, requested_outputs, drive_root_folder_id, status, created_by)
SELECT NULLIF(body->>'external_job_ref',''), COALESCE(NULLIF(body->>'project_name',''),'Untitled AI content job'), COALESCE(body->>'brief_text',''), COALESCE(body->'requested_outputs','[]'::jsonb), NULLIF(body->>'drive_folder_id',''), 'intake_complete', COALESCE(NULLIF(body->>'created_by',''),'api_supervisor') FROM payload
ON CONFLICT (external_job_ref) DO UPDATE SET updated_at=now(), status='intake_complete', brief_text=EXCLUDED.brief_text RETURNING id, status
), msg AS (
INSERT INTO job_messages (job_id, sender_type, sender_id, message_type, message_text, attachments)
SELECT id, 'agent', COALESCE(NULLIF((SELECT body->>'sender_id' FROM payload),''),'supervisor'), 'brief', COALESCE((SELECT body->>'message' FROM payload),(SELECT body->>'brief_text' FROM payload),''), '[]'::jsonb FROM upsert_job RETURNING id
), event AS (
INSERT INTO content_events (job_id, event_type, message, metadata) SELECT id, 'intake_complete', 'Job intake completed', jsonb_build_object('operator_architecture','v2','mode',(SELECT body->>'mode' FROM payload)) FROM upsert_job RETURNING id)
SELECT id::text AS job_id, status::text AS status FROM upsert_job;

